  /**
   * @method
   * @name binance#fetchClosedOrdersWs
   * @description fetch closed orders
   * @see
   * https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/trading-requests#order-lists
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchClosedOrdersWs(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                      ccxt::any limit = ccxt::any{},
                      ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any orders = awaitValue(
                     this->fetchOrdersWs(symbol, since, limit, params));
                 ccxt::any closedOrders = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   ccxt::any order = ::getValue(orders, i);
                   if (isTrue(isEqual(::getValue(order, std::string("status")),
                                      std::string("closed")))) {
                     arrayPush(closedOrders, order);
                   }
                 }
                 return closedOrders;
               })
        .share();
  }

